function shouldRetryError(status, retries, retryStatusCodes) {
  if (retries <= 0 || !retryStatusCodes.includes(status)) return false
  return retryPolicyAllows(status, retries, retryStatusCodes)
}
function retryPolicyAllows(status, retries, retryStatusCodes) {
  return retries > 0 && retryStatusCodes.includes(status)
}
